#pragma once
WINDOWPLACEMENT savedPlacement={sizeof(WINDOWPLACEMENT)};
bool havePlacement=false;
void loadPlacement(const json&j){havePlacement=false;try{if(!j.contains("window"))return;const auto&w=j["window"];int x=w.at("x").get<int>(),y=w.at("y").get<int>(),width=w.at("width").get<int>(),height=w.at("height").get<int>();if(width<400||height<300||width>32768||height>32768||x< -100000||x>100000||y< -100000||y>100000)return;savedPlacement.length=sizeof(savedPlacement);savedPlacement.rcNormalPosition={x,y,x+width,y+height};savedPlacement.showCmd=w.value("maximized",false)?SW_SHOWMAXIMIZED:SW_SHOWNORMAL;havePlacement=true;}catch(...){havePlacement=false;}}
void capturePlacement(){if(!mainWindow||!IsWindow(mainWindow))return;WINDOWPLACEMENT p={sizeof(p)};if(!GetWindowPlacement(mainWindow,&p))return;if(p.showCmd==SW_SHOWMINIMIZED)p.showCmd=(p.flags&WPF_RESTORETOMAXIMIZED)?SW_SHOWMAXIMIZED:SW_SHOWNORMAL;else if(p.showCmd!=SW_SHOWMAXIMIZED)p.showCmd=SW_SHOWNORMAL;savedPlacement=p;havePlacement=true;}
void addPlacement(json&j){capturePlacement();if(!havePlacement)return;const auto&r=savedPlacement.rcNormalPosition;j["window"]={{"x",r.left},{"y",r.top},{"width",r.right-r.left},{"height",r.bottom-r.top},{"maximized",savedPlacement.showCmd==SW_SHOWMAXIMIZED}};}
void restorePlacement(HWND h){if(!havePlacement){ShowWindow(h,SW_SHOWMAXIMIZED);return;}RECT r=savedPlacement.rcNormalPosition;HMONITOR monitor=MonitorFromRect(&r,MONITOR_DEFAULTTONEAREST);MONITORINFO info={sizeof(info)};GetMonitorInfoW(monitor,&info);RECT visible;IntersectRect(&visible,&r,&info.rcWork);bool enough=visible.right-visible.left>=80&&visible.bottom-visible.top>=40;int workWidth=info.rcWork.right-info.rcWork.left,workHeight=info.rcWork.bottom-info.rcWork.top;
 if(!enough||r.right-r.left>workWidth||r.bottom-r.top>workHeight){int width=std::min<int>(r.right-r.left,workWidth),height=std::min<int>(r.bottom-r.top,workHeight);r.left=std::max<LONG>(info.rcWork.left,std::min<LONG>(r.left,info.rcWork.right-width));r.top=std::max<LONG>(info.rcWork.top,std::min<LONG>(r.top,info.rcWork.bottom-height));r.right=r.left+width;r.bottom=r.top+height;savedPlacement.rcNormalPosition=r;}
 savedPlacement.flags=0;savedPlacement.length=sizeof(savedPlacement);SetWindowPlacement(h,&savedPlacement);ShowWindow(h,savedPlacement.showCmd);}
